node --input-type=module -e "const { handle: h } = await import('./src/app.js');
const ok = (c, m) => { if (!c) { console.error('failed: ' + m); process.exit(1); } };
let r = h('GET', '/users/1'); ok(r.status === 200 && r.body.name === 'Ada', 'GET /users/:id');
r = h('GET', '/users/99'); ok(r.status === 404 && typeof r.body.error === 'string' && r.body.code === 404, 'missing user error shape');
r = h('POST', '/users', { name: 'Grace' }); ok(r.status === 201 && r.body.id === 3 && r.body.name === 'Grace', 'POST /users');
r = h('POST', '/users', {}); ok(r.status === 400 && r.body.code === 400 && typeof r.body.error === 'string', 'POST validation');
r = h('GET', '/users?name=gRa'); ok(r.status === 200 && r.body.length === 1 && r.body[0].name === 'Grace', 'name filter');
r = h('DELETE', '/users/3'); ok(r.status === 204, 'DELETE');
r = h('GET', '/users/3'); ok(r.status === 404 && r.body.code === 404, 'deleted user');
r = h('GET', '/nope'); ok(r.status === 404 && r.body.code === 404, 'unknown route error shape');
r = h('GET', '/stats'); ok(r.status === 200 && r.body.users === 2 && r.body.requests >= 8, 'GET /stats');"
